*{box-sizing:border-box} :root{color-scheme:dark;--bg:#0b0c12;--panel:#11121a;--panel2:#15151e;--line:#262631;--muted:#777783;--text:#e9e5e0;--gold:#c5a77b;--red:#bd635f;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif} html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:var(--sans)}body{background-image:radial-gradient(ellipse at 50% 20%,rgba(54,48,66,.14),transparent 55%);padding:0 28px}.game-shell{max-width:1450px;margin:0 auto}.topbar{height:74px;border-bottom:1px solid #22222b;display:flex;align-items:center;justify-content:space-between}.wordmark{display:flex;align-items:center;gap:12px;color:#e8e4de;text-decoration:none;font-size:13px;font-weight:700;letter-spacing:2px}.brand-mark{width:26px;height:26px;border:1px solid #645843;color:#c5a77b;display:grid;place-items:center;font-size:14px;transform:rotate(45deg);line-height:1}.brand-mark::first-letter{transform:rotate(-45deg)}.wordmark-dim{color:#7a6c58;margin:0 3px}.chapter,.sound-button,.eyebrow,.card-index,.stage-topline,.progress-copy,.journal-meta,.route-status,.side-bottom,.page-footer,.intro-hint,.toast,.boss-health-heading,.boss-banner small{font-family:var(--mono);letter-spacing:1px}.chapter{color:#9a9695;font-size:10px;display:flex;align-items:center;gap:12px}.live-dot,.rec-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a36c60;box-shadow:0 0 9px #a36c6088}.chapter-divider{color:#494752}.sound-button{background:none;border:1px solid #292832;color:#a6a0a0;padding:9px 12px;display:flex;gap:9px;align-items:center;font-size:9px;cursor:pointer}.sound-button span:first-child{color:var(--gold);font-size:13px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 286px;gap:22px;padding-top:24px}.main-column{min-width:0}.hud{min-height:73px;background:#11121a;border:1px solid #24242e;display:flex;align-items:center;padding:13px 20px;margin-bottom:12px;gap:26px}.hero-block{display:flex;align-items:center;gap:12px;min-width:220px}.avatar{height:42px;width:42px;background:#25222a;border:1px solid #51423d;display:grid;place-items:center;color:#c4a581;position:relative;font-size:19px}.avatar:before,.avatar:after{content:'';position:absolute;background:#786451}.avatar:before{width:1px;height:50px;left:-5px;top:-5px;opacity:.5}.avatar:after{height:1px;width:50px;left:-5px;top:-5px;opacity:.5}.eyebrow{font-size:9px;color:#89858a;letter-spacing:1.3px}.level-tag{color:#c4a581;margin-left:8px;font-size:8px}.hero-name{font-size:14px;font-weight:600;margin-top:3px}.vitals{flex:1;max-width:280px}.vital-row{display:flex;align-items:center;justify-content:space-between;margin-bottom:7px}.vital-label{font:9px var(--mono);letter-spacing:1px;color:#aaa5a2}.heart-icon{font-style:normal;color:#bb6d67;font-size:12px;margin-right:5px}.vital-count{font:10px var(--mono);color:#c2b9b2}.health-track{display:flex;gap:4px}.heart-segment{height:7px;flex:1;background:#342427;border:1px solid #573438;transition:background .2s}.heart-segment.full{background:#bd6a68;box-shadow:0 0 8px #bd6a6833}.souls{margin-left:auto;border-left:1px solid #2a2932;padding-left:22px;display:flex;align-items:center;gap:10px}.soul-gem{color:#b69b76;font-size:18px;text-shadow:0 0 11px #c19a5e55}.souls strong{display:block;color:#e4d7c3;font:15px var(--mono);margin-top:3px}.stage-frame{background:#11121a;border:1px solid #292832;position:relative}.stage-topline{height:38px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;border-bottom:1px solid #272630;font-size:9px;color:#a39e9b}.location{display:flex;align-items:center;gap:9px;color:#c9bda9}.location-icon{font-size:15px;color:#c5a77b}.stage-readout{font-size:8px;color:#777681;display:flex;gap:8px;align-items:center}.rec-dot{width:5px;height:5px;background:#b26c65}.readout-divider{font-size:14px;color:#615b60}.canvas-wrap{position:relative;background:#111;overflow:hidden;line-height:0}canvas#game{display:block;width:100%;height:auto;aspect-ratio:16/9;image-rendering:pixelated;image-rendering:crisp-edges}.canvas-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(8,9,15,.16),transparent 14%,transparent 86%,rgba(8,9,15,.2)),linear-gradient(0deg,rgba(8,9,15,.18),transparent 20%,transparent 80%,rgba(8,9,15,.16)}.stage-footer{height:62px;border-top:1px solid #272630;display:flex;align-items:center;padding:0 17px;gap:25px}.objective{display:flex;align-items:center;gap:10px;flex:1;min-width:0}.objective-mark{color:#c5a77b;font-size:19px}.objective .eyebrow{font-size:8px}.objective strong{display:block;font-size:11px;font-weight:500;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.progress-wrap{width:180px}.progress-copy{display:flex;justify-content:space-between;color:#87838a;font-size:8px;margin-bottom:7px}.progress-copy span:last-child{color:#bba178}.progress-track{height:3px;background:#34323a}.progress-track div{height:100%;width:0;background:#b99a6c;transition:width .25s}.controls-row{height:43px;display:flex;align-items:center;justify-content:space-between}.controls-hint{display:flex;align-items:center;gap:5px}.keycap{min-width:20px;height:20px;display:grid;place-items:center;border:1px solid #393740;background:#15151d;color:#bbb5b1;font:9px var(--mono);box-shadow:0 2px 0 #07080c;padding:0 4px}.keycap.wide{min-width:41px}.hint-copy{font:8px var(--mono);letter-spacing:.5px;color:#77747c;margin:0 7px 0 2px}.hint-gap{width:7px}.mini-tip{font:9px var(--mono);color:#89848a;letter-spacing:.2px}.tip-spark{color:#b89a6f;margin-right:7px}.side-column{display:flex;flex-direction:column;gap:12px}.side-card{background:#11121a;border:1px solid #262630;padding:16px 17px}.card-head{display:flex;align-items:center;justify-content:space-between}.card-index{font-size:8px;color:#65636d}.map-card h2{font-size:22px;line-height:1.12;margin:18px 0 9px;letter-spacing:-.7px;font-weight:600}.map-card h2 em{font-weight:400;color:#b79d7c}.side-intro{font-size:10px;line-height:1.65;color:#918c92;margin:0 0 15px;max-width:235px}.map-box{height:88px;border:1px solid #2c2a33;background:#0d0e15;position:relative;padding:0 3px}.map-box canvas{width:100%;height:100%;image-rendering:pixelated}.map-labels{position:absolute;left:8px;right:8px;bottom:5px;display:flex;justify-content:space-between;font:7px var(--mono);letter-spacing:.5px;color:#716b71}.route-status{display:flex;align-items:center;gap:7px;margin-top:13px;font-size:7px;color:#8f8988}.route-dot{width:5px;height:5px;background:#8e765d;border-radius:50%;box-shadow:0 0 7px #c19b6544}.route-dash{height:1px;background:#3a3639;flex:1}.route-boss{color:#a76c67}.inventory-card{padding:15px 17px}.inventory-card .card-head{margin-bottom:11px}.item-row{display:flex;align-items:center;gap:10px;padding:10px 0;border-top:1px solid #282730}.item-icon{width:31px;height:31px;border:1px solid #433a39;display:grid;place-items:center;color:#c29a78;background:#211e23;font-size:16px}.flask{color:#a47f91}.item-copy{min-width:0;flex:1}.item-copy strong{display:block;font-size:10px;font-weight:600}.item-copy small{display:block;color:#77747d;font-size:8px;margin-top:4px}.item-count,.weapon-level{font:10px var(--mono);color:#c3a77d}.item-row kbd{font:8px var(--mono);padding:4px 5px;border:1px solid #403c43;color:#9c9694}.weapon-row{padding-bottom:0}.sword{font-size:14px}.weapon-level{color:#89828d}.journal-card{min-height:128px;position:relative;overflow:hidden}.whisper-mark{font:35px Georgia;color:#504348;height:18px}.journal-card p{font-size:12px;line-height:1.55;color:#c8b7a4;font-family:Georgia,serif;font-style:italic;margin:13px 0 14px}.journal-meta{display:flex;align-items:center;gap:7px;color:#68656e;font-size:7px}.journal-line{width:15px;height:1px;background:#76634e}.side-bottom{margin-top:auto;display:flex;align-items:center;gap:8px;padding:5px 3px;color:#6b6670;font-size:7px;letter-spacing:1px}.seal{color:#a18868;font-size:11px}.side-bottom-line{height:1px;background:#292831;flex:1}.page-footer{height:42px;border-top:1px solid #22222a;display:flex;align-items:center;justify-content:space-between;color:#57545e;font-size:8px;letter-spacing:1px;margin-top:8px}.footer-version{color:#77717a}.footer-version i{font-style:normal;color:#ac9067;margin-left:4px}.intro-overlay,.end-overlay{position:absolute;inset:0;z-index:5;display:grid;place-items:center;background:rgba(7,8,13,.44);backdrop-filter:blur(1px);line-height:normal;transition:opacity .3s}.intro-overlay.hidden,.end-overlay.hidden{opacity:0;pointer-events:none}.intro-card{text-align:center;width:min(410px,90%);padding:25px;background:linear-gradient(135deg,rgba(17,17,25,.95),rgba(17,16,24,.84));border:1px solid #51453c;box-shadow:0 14px 60px #06060ac9;position:relative}.intro-card:before,.intro-card:after{content:'';position:absolute;width:18px;height:18px;border-color:#bc9b6b}.intro-card:before{left:-1px;top:-1px;border-left:1px solid;border-top:1px solid}.intro-card:after{right:-1px;bottom:-1px;border-right:1px solid;border-bottom:1px solid}.intro-symbol{font-size:22px;color:#c7a77b;margin-bottom:10px;text-shadow:0 0 16px #b58b5e}.intro-card .eyebrow{font-size:8px;letter-spacing:2px}.intro-card h1{font-size:42px;line-height:.96;letter-spacing:-2px;margin:12px 0;font-weight:600}.intro-card h1 em{font-weight:400;color:#c1a17a}.intro-card p{font-size:11px;line-height:1.7;color:#a39ba0;margin:0 0 18px}.primary-button{background:#ad8d65;border:1px solid #d0b38b;color:#17151a;padding:12px 19px;font:600 9px var(--mono);letter-spacing:1px;cursor:pointer;transition:background .15s,transform .15s}.primary-button:hover{background:#c9a77a;transform:translateY(-1px)}.primary-button span{font-size:14px;margin-left:15px}.intro-hint{font-size:7px;color:#756e75;margin-top:15px;letter-spacing:1px}.intro-hint i{font-style:normal;color:#a18a6b;margin:0 5px}.toast{position:absolute;z-index:4;left:50%;top:15px;transform:translate(-50%,-10px);opacity:0;background:rgba(16,16,22,.92);border:1px solid #53463d;padding:9px 14px;color:#d4be9e;font-size:8px;white-space:nowrap;transition:all .2s;line-height:normal;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.boss-banner{position:absolute;z-index:3;top:15px;left:50%;transform:translate(-50%,-10px);opacity:0;display:flex;align-items:center;gap:9px;padding:8px 13px;background:#180f16dd;border:1px solid #754746;line-height:normal;transition:all .45s;pointer-events:none}.boss-banner.show{opacity:1;transform:translate(-50%,0)}.boss-eye{font-size:19px;color:#bd6c69;text-shadow:0 0 12px #cf5656}.boss-banner b{font:10px var(--mono);letter-spacing:1px;color:#e0c8b7;display:block}.boss-banner small{font-size:7px;color:#9c7474;display:block;margin-top:4px}.boss-health{position:absolute;z-index:3;top:18px;left:50%;transform:translateX(-50%);width:min(300px,70%);opacity:0;transition:opacity .2s;line-height:normal;pointer-events:none}.boss-health.show{opacity:1}.boss-health-heading{display:flex;justify-content:space-between;color:#d0b5ac;font-size:8px;text-shadow:0 1px 3px #000;margin-bottom:5px}.boss-track{height:6px;background:#2c171b;border:1px solid #714145}.boss-track div{height:100%;width:100%;background:#ae4f53;transition:width .2s}.end-overlay{background:rgba(6,7,12,.76);backdrop-filter:blur(3px)}.end-card{text-align:center;padding:28px 36px;background:#12121a;border:1px solid #66503e;min-width:min(360px,90%);box-shadow:0 15px 60px #000}.end-kicker{font:8px var(--mono);letter-spacing:2px;color:#bd9c70}.end-card h2{font-size:24px;letter-spacing:1px;margin:12px 0 8px}.end-card p{color:#9a9291;font-size:11px;margin:0 0 20px}.end-card .primary-button{margin:auto}.touch-controls{display:none}
@media(max-width:1020px){body{padding:0 16px}.game-layout{grid-template-columns:minmax(0,1fr) 250px;gap:14px}.hud{gap:15px;padding:12px}.hero-block{min-width:190px}.side-card{padding:14px}.map-card h2{font-size:20px}.mini-tip{display:none}}
@media(max-width:760px){body{padding:0 10px}.topbar{height:57px}.chapter{font-size:8px;gap:7px}.wordmark{font-size:11px;gap:9px}.sound-button{padding:7px 8px}.sound-label{display:none}.game-layout{grid-template-columns:1fr;padding-top:12px;gap:10px}.side-column{display:grid;grid-template-columns:1fr 1fr;gap:8px}.map-card{grid-row:span 2}.map-card h2{font-size:19px;margin-top:12px}.side-intro{font-size:9px}.inventory-card{padding:12px}.journal-card{min-height:0;padding:12px}.journal-card p{font-size:10px;margin:9px 0}.side-bottom{display:none}.page-footer{margin-top:7px;font-size:6px}.footer-version{display:none}.hud{min-height:61px;padding:8px 10px;gap:9px}.hero-block{min-width:0;flex:1;gap:8px}.avatar{width:35px;height:35px}.hero-name{font-size:11px}.hero-block .eyebrow{font-size:7px}.vitals{flex:1.3}.souls{padding-left:9px;gap:6px}.souls .eyebrow{font-size:7px}.souls strong{font-size:12px}.stage-topline{height:32px;padding:0 9px;font-size:8px}.stage-readout{font-size:7px;gap:5px}.stage-footer{height:52px;padding:0 10px;gap:10px}.objective strong{font-size:9px}.objective .eyebrow{font-size:7px}.objective-mark{font-size:16px}.progress-wrap{width:100px}.progress-copy{font-size:7px}.controls-row{height:38px}.controls-hint{gap:3px}.keycap{height:18px;min-width:18px;font-size:8px}.keycap.wide{min-width:34px}.hint-copy{font-size:7px;margin-right:4px}.hint-gap{width:2px}.intro-card{padding:18px}.intro-card h1{font-size:36px}.intro-card p{font-size:10px}.touch-controls{position:fixed;z-index:10;bottom:max(12px,env(safe-area-inset-bottom));left:0;right:0;padding:0 16px;justify-content:space-between;pointer-events:none}.touch-group{display:flex;gap:8px;pointer-events:auto}.touch-controls button{width:48px;height:48px;border:1px solid #63544a;background:#17171fdd;color:#d6c3a9;font-size:18px;touch-action:none;user-select:none;box-shadow:0 4px 12px #0008}.touch-controls button:active{background:#5e4d3e}.page-footer{height:30px}.stage-frame{margin-bottom:0}}
@media(max-width:420px){.hero-block .level-tag{display:none}.souls{border:0}.vitals{max-width:none}.side-column{grid-template-columns:1fr 1fr}.side-card{padding:10px}.map-card h2{font-size:17px}.map-labels{font-size:6px}.inventory-card .item-copy strong{font-size:9px}.item-copy small{font-size:7px}.item-row{gap:6px}.controls-hint{gap:2px}.hint-copy{margin-left:1px;margin-right:2px}.hint-gap{width:0}.progress-wrap{width:82px}.stage-footer{gap:7px}.objective{gap:6px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap');
  const mctx = mini.getContext('2d');
  const W = canvas.width, H = canvas.height, WORLD = 2600, FLOOR = 454;
  const $ = id => document.getElementById(id);
  const ui = {
    intro: $('introOverlay'), start: $('startButton'), health: $('healthBar'), healthText: $('healthText'),
    shards: $('shardCount'), potions: $('potionCount'), loc: $('locationName'), state: $('stateLabel'), coords: $('coordinates'),
    objective: $('objectiveText'), progress: $('progressText'), progressFill: $('progressFill'), route: $('routeStatus'),
    toast: $('toast'), bossBanner: $('bossBanner'), bossHealth: $('bossHealth'), bossFill: $('bossHealthFill'), bossText: $('bossHealthText'),
    end: $('endOverlay'), endTitle: $('endTitle'), endKicker: $('endKicker'), endText: $('endText'), restart: $('restartButton'),
    whisper: $('whisperText'), tip: $('tipText'), sound: $('soundButton'), soundIcon: $('soundIcon')
  };
  const keys = Object.create(null);
  const platforms = [{x:300,y:385,w:130},{x:535,y:335,w:115},{x:755,y:390,w:150},{x:1040,y:360,w:135},{x:1285,y:320,w:125},{x:1515,y:382,w:150},{x:1740,y:342,w:125},{x:2055,y:390,w:150},{x:2350,y:350,w:130}];
  const initialEnemies = [
    {x:445,y:FLOOR,w:24,h:30,hp:2,phase:0}, {x:900,y:FLOOR,w:24,h:30,hp:2,phase:1.5},
    {x:1185,y:FLOOR,w:24,h:30,hp:2,phase:2.5}, {x:1600,y:FLOOR,w:24,h:30,hp:2,phase:.7},
    {x:1810,y:FLOOR,w:24,h:30,hp:2,phase:3}
  ];
  const trees = [];
  for(let i=0;i<42;i++) trees.push({x:i*78-40+(i%3)*16,h:125+(i*37%100),w:19+(i*13%20),tone:i%3});
  let player, enemies, boss, shards, camera, active, ended, time, particles, projectiles, attackFlash, toastTimer, lastTime, soundOn, audio;
  let collected = new Set();
  const reset = () => {
    player={x:75,y:FLOOR,w:22,h:34,vx:0,vy:0,health:5,maxHealth:5,facing:1,grounded:true,invuln:0,attackCd:0,attackTime:0,potions:2,shards:0,walk:0};
    enemies=initialEnemies.map(e=>({...e,alive:true,hitFlash:0}));
    boss={x:2290,y:FLOOR,w:60,h:72,hp:8,maxHp:8,alive:true,phase:0,attackTimer:2,hitFlash:0,telegraph:0};
    camera=0;time=0;particles=[];projectiles=[];attackFlash=0;ended=false;collected=new Set();
    updateHud(); setObjective(); ui.bossHealth.classList.remove('show');ui.bossBanner.classList.remove('show');ui.end.classList.add('hidden');
  };
  reset(); active=false; soundOn=false; lastTime=performance.now();

  function updateHud(){
    ui.health.innerHTML='';
    for(let i=0;i<player.maxHealth;i++){const s=document.createElement('span');s.className='heart-segment'+(i<player.health?' full':'');ui.health.appendChild(s)}
    ui.healthText.textContent=`${player.health} / ${player.maxHealth}`;
    ui.shards.textContent=String(player.shards).padStart(2,'0');ui.potions.textContent=`× ${player.potions}`;
  }
  function setObjective(){
    const alive=enemies.filter(e=>e.alive).length;
    if(boss.alive){
      if(player.x<480){ui.objective.textContent='Follow the lanterns into the wood';ui.tip.innerHTML='<span class="tip-spark">✦</span> Stay light on your feet, wanderer.'}
      else if(player.x<1810){ui.objective.textContent=`Find the old road · ${alive} wisp${alive===1?'':'s'} remain`;ui.tip.innerHTML='<span class="tip-spark">✦</span> A clean strike will scatter the restless.'}
      else {ui.objective.textContent='The Hollow King stirs beyond the veil';ui.tip.innerHTML='<span class="tip-spark">✦</span> Keep moving when the ground begins to glow.'}
    }else{ui.objective.textContent='The old road is open. The wood falls quiet.'}
  }
  let toastId=0;
  function toast(message){ui.toast.textContent=message;ui.toast.classList.add('show');clearTimeout(toastId);toastId=setTimeout(()=>ui.toast.classList.remove('show'),1550)}
  function beep(freq=200,duration=.08,type='sine',volume=.035){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.value=volume;o.connect(g);g.connect(audio.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.stop(audio.currentTime+duration)}catch(_){}}
  function startGame(){if(ended)return;active=true;ui.intro.classList.add('hidden');toast('THE OLD ROAD REMEMBERS');beep(260,.16,'triangle')}
  ui.start.addEventListener('click',startGame);
  ui.restart.addEventListener('click',()=>{reset();active=true;ui.intro.classList.add('hidden');toast('THE ROAD CALLS AGAIN')});
  ui.sound.addEventListener('click',()=>{soundOn=!soundOn;ui.soundIcon.textContent=soundOn?'♫':'♩';ui.sound.style.borderColor=soundOn?'#716044':'';if(soundOn)beep(390,.1,'sine')});

  function jump(){if(!active||ended)return;if(player.grounded){player.vy=-430;player.grounded=false;beep(240,.07,'triangle',.02)}}
  function attack(){if(!active||ended)return;if(player.attackCd>0)return;player.attackCd=.34;player.attackTime=.2;beep(210,.08,'sawtooth',.018);
    const hit=(target,isBoss=false)=>{const dx=target.x-player.x;const reach=isBoss?80:60;if(Math.abs(dx)<reach&&((dx>=0?1:-1)===player.facing||Math.abs(dx)<20)){
      target.hp--;target.hitFlash=.18;burst(target.x+(target.w||24)/2,target.y-(target.h||30)/2,isBoss?'#d18b80':'#c6a579',9);
      if(isBoss){boss.hp=Math.max(0,boss.hp);ui.bossFill.style.width=(boss.hp/boss.maxHp*100)+'%';ui.bossText.textContent=`${boss.hp} / ${boss.maxHp}`;if(boss.hp<=0)win()}
      else if(target.hp<=0){target.alive=false;player.shards++;updateHud();beep(540,.14,'sine',.025);toast('A GLOAM SHARD · +1')}
    }};
    enemies.forEach(e=>{if(e.alive)hit(e)});if(boss.alive&&player.x>1840)hit(boss,true);
  }
  function heal(){if(!active||ended)return;if(!player.potions){toast('NO TONICS LEFT');return}if(player.health>=player.maxHealth){toast('VITALITY IS ALREADY WHOLE');return}player.potions--;player.health=Math.min(player.maxHealth,player.health+2);updateHud();burst(player.x+10,player.y-18,'#9b7896',12);beep(440,.2,'sine',.03);toast('WITCH’S TONIC · +2 VITALITY')}
  function takeDamage(amount=1){if(player.invuln>0||ended)return;player.health=Math.max(0,player.health-amount);player.invuln=1.05;player.vy=-180;player.vx=-player.facing*95;updateHud();burst(player.x+10,player.y-16,'#c45f60',8);beep(100,.22,'square',.03);if(player.health<=0)finish(false)}
